+fn pick(world: &World, layer: &str) -> GeoSel {
+    let (_, drawing) = sketch::find(world, "drawing").expect("drawing");
+    let chain = drawing.data.chains().by_layer(layer)[0].id();
+    GeoSel {
+        entity: "drawing".into(),
+        feature: FeatureSel::SketchChain(chain),
+    }
